Section Rb2.
Context {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Section Segs.
  Context {fx : FPState}.
  Variable rom : word -> option byte.

  Ltac pxo PX := repeat (apply PIXat_out; [| rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; lia | rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn; lia]); exact PX.

  (* [comment removed for export] *)
  Lemma rb_A1 : forall regs m (s pixs tab : Z) (v : pixv) (ret : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 96 \/ s <= pixs)%Z -> p_d v = 1%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 96)) 96 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs -> getr regs 11 = Z_to_bv 64 1 ->
    getr regs 12 = Z_to_bv 64 tab ->
    exists regs',
      msteps SEGS (mkst regs (0x940fc : word) m rom) (mkst regs' (0x94204 : word) (MRB_A m s v ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 96) /\ getr regs' 9 = Z_to_bv 64 pixs /\ getr regs' 19 = Z_to_bv 64 1
      /\ getr regs' 23 = Z_to_bv 64 tab
      /\ regs_agree (fun r => In r [1; 2; 9; 10; 11; 12; 13; 14; 19; 23]%list) regs regs'.
Proof.
