  Lemma rb_A2 : forall regs m (s pixs h : Z) (v : pixv),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (2 <= h < 2 ^ 31)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 80)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
    getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 9 = Z_to_bv 64 pixs ->
    exists regs',
      msteps SEGS (mkst regs (0x94204 : word) m rom) (mkst regs' (0x6ed1c : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x9425c /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 0
      /\ getr regs' 18 = Z_to_bv 64 (p_wpl v) /\ getr regs' 8 = Z_to_bv 64 (p_data v)
      /\ regs_agree (fun r => In r [1; 8; 10; 11; 18]%list) regs regs'.
