  (* [comment removed for export] *)
  Lemma rb_Ah : forall regs m (s h : Z),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= h <= 1)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 80)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
    rdn SEGS m (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) -> rdn SEGS m (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 2 = Z_to_bv 64 (s - 96) ->
    exists regs',
      msteps SEGS (mkst regs (0x94204 : word) m rom) (mkst regs' (0x6311c : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x94404 /\ getr regs' 10 = Z_to_bv 64 0x16354 /\ getr regs' 11 = Z_to_bv 64 0x1636a /\ getr regs' 12 = Z_to_bv 64 0
      /\ regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs'.
