  (* [comment removed for export] *)
  Lemma rb_B : forall regs m (s w h : Z),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= w < 2 ^ 31)%Z -> (0 <= h < 2 ^ 31)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 76)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 w)) ->
    rdn SEGS m (Z_to_bv 64 (s - 80)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
    getr regs 2 = Z_to_bv 64 (s - 96) ->
    exists regs',
      msteps SEGS (mkst regs (0x9425c : word) m rom) (mkst regs' (0x6c638 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x94284 /\ getr regs' 10 = Z_to_bv 64 (w / 2) /\ getr regs' 11 = Z_to_bv 64 (h / 2) /\ getr regs' 12 = Z_to_bv 64 1
