  (* [comment removed for export] *)
  Lemma rb_R : forall regs m (i wplsi wpld datad ps ps2 pd : Z),
    (0 <= i < 2 ^ 31)%Z -> (1 <= wplsi < 2 ^ 31)%Z -> (1 <= wpld < 2 ^ 24)%Z -> (0 <= datad)%Z ->
    getr regs 13 = Z_to_bv 64 wplsi -> getr regs 20 = Z_to_bv 64 (4 * wpld) -> getr regs 14 = Z_to_bv 64 i ->
    getr regs 5 = Z_to_bv 64 (datad + 2 * wplsi) -> getr regs 8 = Z_to_bv 64 ps -> getr regs 16 = Z_to_bv 64 ps2 -> getr regs 9 = Z_to_bv 64 pd ->
    exists regs',
      msteps SEGS (mkst regs (0x94360 : word) m rom) (mkst regs' (0x94378 : word) m rom)
      /\ getr regs' 6 = Z_to_bv 64 (datad + 2 * wplsi + 4 * wpld * i) /\ getr regs' 7 = Z_to_bv 64 ps /\ getr regs' 28 = Z_to_bv 64 ps2
      /\ getr regs' 29 = Z_to_bv 64 pd
      /\ regs_agree (fun r => In r [6; 7; 28; 29]%list) regs regs'.
Proof.
