  (* [comment removed for export] *)
  Lemma rb_W : forall regs m (ps ps2 pd tab : Z) (b1 b2 : list byte) (v1 v2 : word) (tb : Z -> byte),
    (0 <= ps)%Z -> (ps + 4 < 2 ^ 64)%Z -> (0 <= ps2)%Z -> (ps2 + 4 < 2 ^ 64)%Z -> (0 <= pd)%Z -> (pd + 4 < 2 ^ 64)%Z ->
    (0 <= tab)%Z -> (tab + 256 < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 ps) 4 = Some b1 -> bytes_le_to_Z b1 = bv_unsigned v1 ->
    rdn SEGS m (Z_to_bv 64 ps2) 4 = Some b2 -> bytes_le_to_Z b2 = bv_unsigned v2 ->
    (forall i : Z, (0 <= i < 256)%Z -> rdn SEGS m (Z_to_bv 64 (tab + i)) 1 = Some [tb i]) ->
    store_ok SEGS m (Z_to_bv 64 (Z.lxor pd 2)) 2 = true ->
    getr regs 7 = Z_to_bv 64 ps -> getr regs 28 = Z_to_bv 64 ps2 -> getr regs 29 = Z_to_bv 64 pd -> getr regs 11 = Z_to_bv 64 tab ->
    exists regs' (wv : word),
      msteps SEGS (mkst regs (0x94378 : word) m rom)
                  (mkst regs' (0x943d0 : word) (wbytes m (Z_to_bv 64 (Z.lxor pd 2)) (word_to_le_bytes 2 wv)) rom)
      /\ getr regs' 7 = Z_to_bv 64 (ps + 4) /\ getr regs' 28 = Z_to_bv 64 (ps2 + 4) /\ getr regs' 29 = Z_to_bv 64 (pd + 2)
      /\ regs_agree (fun r => In r [7; 28; 29; 30; 31]%list) regs regs'.
