  Lemma rb_Rn : forall regs m (i hd wpld wpls ps ps2 pd : Z),
    (0 <= i)%Z -> (i + 1 < hd)%Z -> (hd < 2 ^ 31)%Z ->
    getr regs 14 = Z_to_bv 64 i -> getr regs 17 = Z_to_bv 64 hd -> getr regs 20 = Z_to_bv 64 (4 * wpld) -> getr regs 18 = Z_to_bv 64 (8 * wpls) ->
    getr regs 8 = Z_to_bv 64 ps -> getr regs 16 = Z_to_bv 64 ps2 -> getr regs 9 = Z_to_bv 64 pd ->
    exists regs',
      msteps SEGS (mkst regs (0x9434c : word) m rom) (mkst regs' (0x94360 : word) m rom)
      /\ getr regs' 14 = Z_to_bv 64 (i + 1) /\ getr regs' 8 = Z_to_bv 64 (ps + 8 * wpls) /\ getr regs' 16 = Z_to_bv 64 (ps2 + 8 * wpls)
      /\ getr regs' 9 = Z_to_bv 64 (pd + 4 * wpld)
      /\ regs_agree (fun r => In r [8; 9; 14; 16]%list) regs regs'.
Proof.
