  (* [comment removed for export] *)
  Lemma rb_Rx : forall regs m (s i tab : Z) (ret s0v s1v s2v s3v s4v s5v s6v s7v : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret -> (0 <= i)%Z -> (i + 1 < 2 ^ 31)%Z -> (1 <= tab < 2 ^ 64)%Z ->
    cellsZ m [(s - 8, ret); (s - 16, s0v); (s - 24, s1v); (s - 32, s2v); (s - 40, s3v); (s - 48, s4v); (s - 56, s5v); (s - 64, s6v); (s - 72, s7v)]%Z ->
    getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 14 = Z_to_bv 64 i -> getr regs 17 = Z_to_bv 64 (i + 1) -> getr regs 12 = Z_to_bv 64 tab ->
    exists regs',
      msteps SEGS (mkst regs (0x9434c : word) m rom) (mkst regs' ret m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = getr regs 10
      /\ getr regs' 8 = s0v /\ getr regs' 9 = s1v /\ getr regs' 18 = s2v /\ getr regs' 19 = s3v /\ getr regs' 20 = s4v
      /\ getr regs' 21 = s5v /\ getr regs' 22 = s6v /\ getr regs' 23 = s7v
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 14; 16; 18; 19; 20; 21; 22; 23]%list) regs regs'.
