(* [comment removed for export] *)
Lemma rb_C : forall (rom : word -> option byte) (fr : bvmap 5 word) (cs : bv 32) regs m (s pixd pixs : Z) (vs : pixv),
  (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixd)%Z -> (pixd + 64 < 2 ^ 64)%Z -> (1 <= pixs)%Z -> pixd <> pixs ->
  PIXat m pixs vs -> p_xres vs = 0%Z -> p_yres vs = 0%Z ->
  (pixs + 64 <= s - 96 \/ s <= pixs)%Z -> (pixs + 64 <= pixd \/ pixd + 64 <= pixs)%Z -> (pixd + 64 <= s - 96 \/ s <= pixd)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 88)) 8 = true -> store_ok SEGS m (Z_to_bv 64 (pixd + 24)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 10 = Z_to_bv 64 pixd -> getr regs 9 = Z_to_bv 64 pixs ->
  exists fr' regs',
    msteps SEGS (@mkst (mkFP fr cs) regs (0x94284 : word) m rom) (@mkst (mkFP fr' cs) regs' (0x6defc : word) (MRB_C m s pixd) rom)
    /\ fpv_read fr' FMT_S 10 = F05 /\ fpv_read fr' FMT_S 11 = F05
    /\ (forall r : reg, In (bv_unsigned r) fs_list -> reg_get fr' r = reg_get fr r)
    /\ getr regs' 1 = Z_to_bv 64 0x942ac /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 21 = Z_to_bv 64 pixd
    /\ regs_agree (fun r => In r [1; 10; 11; 12; 21]%list) regs regs'.
